func (u *ModpackUpsertOne) Update(set func(*ModpackUpsert)) *ModpackUpsertOne {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&ModpackUpsert{UpdateSet: update})
	}))
	return u
}

